func (r *HeartbeatResource) Update(ctx context.Context, req resource.UpdateRequest, resp *resource.UpdateResponse) {
	var plan HeartbeatModel
	resp.Diagnostics.Append(req.Plan.Get(ctx, &plan)...)
	var request HeartbeatModel
	resp.Diagnostics.Append(configWithPlannedUnknowns(ctx, req.Config, req.Plan, req.State.Raw, &request)...)
	var state HeartbeatModel
	resp.Diagnostics.Append(req.State.Get(ctx, &state)...)
	if resp.Diagnostics.HasError() {
		return
	}
	// An unset line's default travels only when it changes the stored value (the line was just
	// removed): resending an unchanged default can act on its own, e.g. unpause a group's members.
	if !plan.Paused.Equal(state.Paused) {
		request.Paused = plan.Paused
	}
	vars := map[string]string{}
	vars["id"] = plan.Id.ValueString()
	out, err := r.client.Update(ctx, heartbeatBinding, vars, r.updateBody(ctx, request, plan, state))
	if err != nil {
		addAPIError(&resp.Diagnostics, "updating heartbeat", err, req.Plan.Raw.Type())
		return
	}
	if out == nil {
		out = map[string]interface{}{}
	}
	resp.State.Raw = stateFromPlan(req.Plan.Raw, req.State.Raw, out)
}

func (r *HeartbeatResource) Delete(ctx context.Context, req resource.DeleteRequest, resp *resource.DeleteResponse) {
	var state HeartbeatModel
	resp.Diagnostics.Append(req.State.Get(ctx, &state)...)
	if resp.Diagnostics.HasError() {
		return
	}
	vars := map[string]string{}
	vars["id"] = state.Id.ValueString()
	if err := r.client.Delete(ctx, heartbeatBinding, vars); err != nil {
		addAPIError(&resp.Diagnostics, "deleting heartbeat", err, req.State.Raw.Type())
	}
}

